// Combine deterministic policy rules, AI classification and validation results
// into a single escalation reason. Critical decisions are never LLM-only.
const envelope = $input.first().json;
const policy = envelope.policy || {};
const classification = envelope.classification || {};
const sentiment = envelope.sentiment || {};
const validation = envelope.validation || {};

const reasons = Array.isArray(policy.rules) ? policy.rules.slice() : [];
if (classification.requires_human) reasons.push('human_request');
if (Array.isArray(validation.issues) && validation.issues.length) reasons.push('response_validation_failed');
if (policy.refund_above_threshold) reasons.push('refund_above_threshold');
if (!reasons.length) reasons.push('manual_escalation');

const reason = reasons.join('|');
const subject = `[${(classification.intent || 'support').toUpperCase()}] ${(envelope.message || '').slice(0, 80)}`;

return [{ json: { ...envelope, escalation_reason: reason, escalation_subject: subject } }];

// The SELECT can return zero rows, so normalize to a single item with a flag.
const rows = $('Check Active Ticket').all().map(i => i.json);
const found = rows.length > 0 ? rows[0] : null;
return [{ json: { ...$('Build Escalation Reason').first().json, active_ticket: found, ticket_found: !!found } }];

const base = $('Build Escalation Reason').first().json;
const ticket = $('Insert Ticket').first().json;
const priority = base.policy && base.policy.priority ? base.policy.priority : (ticket.priority || 'normal');
const sentiment = base.sentiment ? base.sentiment.sentiment : '';

let handoff = `Your request has been escalated to a human support agent. A ticket has been created${ticket ? ` (#${ticket.ticket_number})` : ''} and our team will follow up with you shortly.`;
if (sentiment === 'angry' || sentiment === 'frustrated') {
  handoff = `I'm really sorry you're having a frustrating experience. I've escalated your case${ticket ? ` (#${ticket.ticket_number})` : ''} to a human specialist who will take care of it right away.`;
} else if (base.policy && base.policy.refund_above_threshold) {
  handoff = `Your refund request has been forwarded for manual review${ticket ? ` (#${ticket.ticket_number})` : ''}. A specialist will review it and get back to you within 24 hours.`;
}

return [{ json: { ...base, policy: { ...(base.policy || {}), action: 'escalate', requires_human: true, priority }, escalation: { requires_human: true, reason: base.escalation_reason, ticket, handoff_message: handoff } } }];

const base = $('Build Escalation Reason').first().json;
const ticket = $('Normalize Ticket Check').first().json.active_ticket;
const priority = base.policy && base.policy.priority ? base.policy.priority : (ticket.priority || 'normal');
const sentiment = base.sentiment ? base.sentiment.sentiment : '';

let handoff = `Your request is already being handled by our team${ticket ? ` (ticket #${ticket.ticket_number})` : ''}. A human agent will follow up with you shortly.`;
if (sentiment === 'angry' || sentiment === 'frustrated') {
  handoff = `I'm really sorry you're having a frustrating experience. Your case${ticket ? ` (#${ticket.ticket_number})` : ''} is already assigned to a human specialist.`;
}

return [{ json: { ...base, policy: { ...(base.policy || {}), action: 'escalate', requires_human: true, priority }, escalation: { requires_human: true, reason: base.escalation_reason, ticket, handoff_message: handoff } } }];
